// Emits src/generated/dbcLayouts.ts from the vendored WoWDBDefs definitions.
//
// The gateway needs the layouts at compile time — named fields, checked by tsc — and must not
// parse .dbd text at startup. This is the same arrangement as tools/generate-protocol.mjs: the
// generated file is committed, and `--check` fails the build if it has drifted from its source.

import { readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { LOCALES, loadDbdLayout } from "./dbd.mjs";
import { DBD_TABLES } from "./dbd-tables.mjs";
import { WOTLK_BUILD } from "./dbc.mjs";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const destination = resolve(root, "src/generated/dbcLayouts.ts");
const check = process.argv.includes("--check");

const TYPE_CODE = { int: 0, float: 1, string: 2, locstring: 3 };

const tables = [];
for (const table of [...DBD_TABLES].sort()) {
  const layout = await loadDbdLayout(table, WOTLK_BUILD);
  tables.push({ table, layout });
}

const lines = [];
lines.push("// Generated by tools/generate-dbc-layouts.mjs from the WoWDBDefs definitions vendored");
lines.push("// under tools/dbd (CC BY-SA 4.0 — see tools/dbd/README.md). Do not edit by hand;");
lines.push("// run `npm run dbc:generate`. `npm run build` fails if this file has drifted.");
lines.push("//");
lines.push(`// Build ${WOTLK_BUILD.join(".")}, ${tables.length} tables.`);
lines.push("");
lines.push("/** How a field is stored. Every WDBC slot is a word unless the definition says narrower. */");
lines.push('export type DbcFieldType = "int" | "float" | "string" | "locstring";');
lines.push("");
lines.push("export interface DbcField {");
lines.push("  /** Slot index within the record, counting each array element and locale separately. */");
lines.push("  readonly index: number;");
lines.push("  readonly byteOffset: number;");
lines.push("  readonly byteSize: number;");
lines.push("  readonly arraySize: number;");
lines.push("  /** Slots one element occupies: 17 for a localised string, 1 otherwise. */");
lines.push("  readonly stride: number;");
lines.push("  readonly type: DbcFieldType;");
lines.push("  readonly unsigned: boolean;");
lines.push("}");
lines.push("");
lines.push("export interface DbcLayout {");
lines.push("  readonly fieldCount: number;");
lines.push("  readonly recordSize: number;");
lines.push("  /** The `$id$` field, which every table this project reads has. */");
lines.push("  readonly idField: string;");
lines.push("  readonly fields: Readonly<Record<string, DbcField>>;");
lines.push("}");
lines.push("");
lines.push("/** Locale order of the sixteen slots of a localised string, as the client writes them. */");
lines.push(`export const DBC_LOCALES = ${JSON.stringify(LOCALES)} as const;`);
lines.push("export type DbcLocale = (typeof DBC_LOCALES)[number];");
lines.push("/** Sixteen strings plus the mask that says which are filled. */");
lines.push("export const DBC_LOCSTRING_FIELDS = 17;");
lines.push("");
lines.push("export const DBC_LAYOUTS = {");
for (const { table, layout } of tables) {
  const id = layout.fields.find((field) => field.isId);
  lines.push(`  ${table}: {`);
  lines.push(`    fieldCount: ${layout.fieldCount},`);
  lines.push(`    recordSize: ${layout.recordSize},`);
  lines.push(`    idField: ${JSON.stringify(id ? id.name : "")},`);
  lines.push("    fields: {");
  for (const field of layout.fields) {
    const parts = [
      `index: ${field.index}`,
      `byteOffset: ${field.byteOffset}`,
      `byteSize: ${field.byteSize}`,
      `arraySize: ${field.arraySize}`,
      `stride: ${field.stride}`,
      `type: ${JSON.stringify(field.type)}`,
      `unsigned: ${field.unsigned ?? false}`,
    ];
    lines.push(`      ${JSON.stringify(field.name)}: { ${parts.join(", ")} },`);
  }
  lines.push("    },");
  lines.push("  },");
}
lines.push("} as const satisfies Record<string, DbcLayout>;");
lines.push("");
lines.push("export type DbcTable = keyof typeof DBC_LAYOUTS;");
lines.push("");
const generated = lines.join("\n") + "\n";

if (check) {
  let current;
  try {
    current = await readFile(destination, "utf8");
  } catch {
    current = "";
  }
  if (current.replaceAll("\r\n", "\n") !== generated) {
    throw new Error("src/generated/dbcLayouts.ts is out of date. Run `npm run dbc:generate`.");
  }
  console.log(`dbcLayouts.ts is current: ${tables.length} tables, build ${WOTLK_BUILD.join(".")}`);
} else {
  await writeFile(destination, generated);
  const fields = tables.reduce((total, entry) => total + entry.layout.fields.length, 0);
  console.log(`Generated src/generated/dbcLayouts.ts: ${tables.length} tables, ${fields} named fields`);
}
